<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\{Idea,User};
use App\Services\{Administration as A,ProgrammeAccess,PortalNotifications,AutoAllocator};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\{Rule,ValidationException};
class ReviewController extends Controller {
 private function scope(Request $r,ProgrammeAccess $a):array{$ids=$a->programmes($r->user(),'reviews.manage');abort_unless($ids,403);return $ids;}
 public function teams(Request $r,ProgrammeAccess $a){$ids=$this->scope($r,$a);return ['teams'=>DB::table('evaluator_teams')->whereIn('programme_id',$ids)->orderBy('name')->get()->map(fn($team)=>['id'=>$team->id,'programme_id'=>$team->programme_id,'name'=>$team->name,'member_ids'=>DB::table('evaluator_team_members')->where('team_id',$team->id)->pluck('user_id')])];}
 public function saveTeam(Request $r,ProgrammeAccess $a){$ids=$this->scope($r,$a);$d=$r->validate(['programme_id'=>['required','integer',Rule::in($ids)],'name'=>'required|string|max:120','member_ids'=>'required|array|min:1|max:20','member_ids.*'=>'required|integer|distinct|exists:users,id']);foreach($d['member_ids'] as $id){$u=User::findOrFail($id);abort_unless($a->allows($u,$d['programme_id'],'reviews.evaluate'),422,'Every team member must have evaluator access to this programme.');}return DB::transaction(function()use($r,$d){$id=DB::table('evaluator_teams')->insertGetId(['programme_id'=>$d['programme_id'],'name'=>trim($d['name']),'created_at'=>now(),'updated_at'=>now()]);foreach($d['member_ids'] as $userId)DB::table('evaluator_team_members')->insert(['team_id'=>$id,'user_id'=>$userId]);A::audit($r->user(),'evaluator_team.created','evaluator_team',$id,$d,$d['programme_id']);return response()->json(['id'=>$id],201);});}
 public function deleteTeam(Request $r,int $team,ProgrammeAccess $a){$row=DB::table('evaluator_teams')->where('id',$team)->first();abort_unless($row&&in_array($row->programme_id,$this->scope($r,$a)),404);DB::table('evaluator_teams')->where('id',$team)->delete();A::audit($r->user(),'evaluator_team.deleted','evaluator_team',$team,['name'=>$row->name],$row->programme_id);return response()->noContent();}
 public function index(Request $r,ProgrammeAccess $a){$ids=$this->scope($r,$a);$users=User::whereIn('id',DB::table('programme_role_user')->whereIn('programme_id',$ids)->select('user_id'))->orderBy('name')->get()->map(function($u)use($ids,$a){return ['id'=>$u->id,'name'=>$u->name,'email'=>$u->email,'expertise'=>$u->expertise,'preferences'=>DB::table('reviewer_preferences')->where('user_id',$u->id)->whereIn('programme_id',$ids)->get(['programme_id','category']),'availability'=>$u->availability,'status'=>A::active($u)?'active':'inactive','evaluator_programmes'=>array_values(array_intersect($ids,$a->programmes($u,'reviews.evaluate'))),'adjudicator_programmes'=>array_values(array_intersect($ids,$a->programmes($u,'reviews.adjudicate')))];});$assignments=DB::table('review_assignments as a')->join('ideas','ideas.id','=','a.idea_id')->join('users','users.id','=','a.user_id')->join('review_templates as t','t.id','=','a.template_id')->whereIn('ideas.programme_id',$ids)->select('a.*','ideas.title','ideas.programme_id','users.name','t.name as template_name','t.version as template_version')->orderByDesc('a.id')->get();return ['reviewers'=>$users,'assignments'=>$assignments,'templates'=>DB::table('review_templates')->whereIn('programme_id',$ids)->get(),'applications'=>Idea::whereIn('programme_id',$ids)->orderBy('id')->get(['id','title','team','programme_id','status','complete']),'programmes'=>DB::table('programmes')->whereIn('id',$ids)->get()];}
 public function allocate(Request $r,Idea $idea,ProgrammeAccess $a){$ids=$this->scope($r,$a);abort_unless(in_array($idea->programme_id,$ids),404);$r->merge(['adjudicator_id'=>$r->input('adjudicator_id')?:null,'adjudication_template_id'=>$r->input('adjudication_template_id')?:null]);$d=$r->validate(['evaluator_ids'=>'required|array|min:1|max:20','evaluator_ids.*'=>'required|integer|distinct|exists:users,id','adjudicator_id'=>'nullable|integer|exists:users,id','lead_id'=>'required|integer','template_id'=>'required|integer|exists:review_templates,id','adjudication_template_id'=>'nullable|required_with:adjudicator_id|integer|exists:review_templates,id','due_date'=>'nullable|date|after_or_equal:today','reason'=>'nullable|string|max:2000']);return DB::transaction(function()use($r,$idea,$a,$d){$i=Idea::lockForUpdate()->findOrFail($idea->id);$fail=fn($m)=>throw ValidationException::withMessages(['allocation'=>$m]);if(!in_array($i->status,['ready','pending','assigned'])||$i->complete<100)$fail('Only complete applications awaiting or undergoing review can be allocated.');if($d['adjudicator_id']&&in_array($d['adjudicator_id'],$d['evaluator_ids']))$fail('The adjudicator must be independent of the evaluators.');if(!in_array($d['lead_id'],$d['evaluator_ids']))$fail('Choose a lead from the selected evaluators.');$active=DB::table('review_assignments')->where('idea_id',$i->id)->where('active',true)->get();if($active->isNotEmpty()&&mb_strlen(trim($d['reason']??''))<5)$fail('Record a reason before changing an existing allocation.');if($active->contains('status','submitted'))$fail('Submitted assessments are preserved and cannot be reassigned in this workflow.');
  foreach([['evaluation',$d['template_id']],['adjudication',$d['adjudication_template_id']]] as [$kind,$tid]){ if(!$tid)continue;$t=DB::table('review_templates')->where('id',$tid)->lockForUpdate()->first();if(!$t||$t->programme_id!=$i->programme_id||!$t->active||$t->kind!==$kind)$fail('Choose an active matching template from this programme.');}
  foreach(array_filter([...$d['evaluator_ids'],$d['adjudicator_id']]) as $uid){$u=User::lockForUpdate()->findOrFail($uid);$permission=in_array($uid,$d['evaluator_ids'])?'reviews.evaluate':'reviews.adjudicate';if(!$a->allows($u,$i->programme_id,$permission)||$u->availability!=='available')$fail('A reviewer is inactive, unavailable, expired or lacks programme access.');if(!empty($d['due_date'])&&$u->access_expires_at&&substr($u->access_expires_at,0,10)<$d['due_date'])$fail('A reviewerâ€™s access expires before the deadline.');}
  DB::table('review_assignments')->where('idea_id',$i->id)->where('active',true)->update(['active'=>false,'updated_at'=>now()]);
  foreach(array_filter([...$d['evaluator_ids'],$d['adjudicator_id']]) as $uid){$kind=in_array($uid,$d['evaluator_ids'])?'evaluation':'adjudication';$prior=$active->first(fn($x)=>$x->user_id==$uid&&$x->kind===$kind);$tid=$kind==='evaluation'?$d['template_id']:$d['adjudication_template_id'];if($prior&&$prior->started_at&&$prior->template_id!=$tid)$fail('A template is locked once a reviewer has started.');DB::table('review_assignments')->insert(['idea_id'=>$i->id,'user_id'=>$uid,'template_id'=>$tid,'kind'=>$kind,'status'=>$prior?->status??'pending','started_at'=>$prior?->started_at,'marks'=>$prior?->marks,'overall_comment'=>$prior?->overall_comment,'review_notes'=>$prior?->review_notes,'completed_sections'=>$prior?->completed_sections,'recommendation'=>$prior?->recommendation,'active'=>true,'is_lead'=>$uid==$d['lead_id'],'due_date'=>$d['due_date']??null,'assigned_by'=>$r->user()->id,'reason'=>$d['reason']??null,'created_at'=>now(),'updated_at'=>now()]);}
  $i->status='assigned';$i->allocation_wait_reason=null;$i->save();foreach($d['evaluator_ids'] as $uid)PortalNotifications::assigned($uid,$i);DB::table('portal_notifications')->where('idea_id',$i->id)->where('kind','allocation_needed')->update(['read_at'=>now(),'updated_at'=>now()]);A::audit($r->user(),'review.allocated','idea',$i->id,$d,$i->programme_id);return ['message'=>'Review allocation saved.'];});}
 private function templateData(Request $r,array $ids):array{return $r->validate(['programme_id'=>['required','integer',Rule::in($ids)],'name'=>'required|string|max:120','kind'=>['required',Rule::in(['evaluation','adjudication'])],'criteria'=>'required|array|min:1|max:30','criteria.*.name'=>'required|string|max:150','criteria.*.max'=>'required|integer|min:1|max:1000']);}
 public function templates(Request $r,ProgrammeAccess $a){$ids=$a->programmes($r->user(),'templates.manage');abort_unless($ids,403);$d=$this->templateData($r,$ids);return DB::transaction(function()use($r,$d){$id=DB::table('review_templates')->insertGetId(['programme_id'=>$d['programme_id'],'name'=>$d['name'],'kind'=>$d['kind'],'version'=>1,'criteria'=>json_encode($d['criteria']),'active'=>true,'created_at'=>now(),'updated_at'=>now()]);A::audit($r->user(),'template.created','template',$id,['name'=>$d['name']],$d['programme_id']);return response()->json(['id'=>$id],201);});}
 public function updateTemplate(Request $r,int $template,ProgrammeAccess $a){$ids=$a->programmes($r->user(),'templates.manage');abort_unless($ids,403);$d=$this->templateData($r,$ids);return DB::transaction(function()use($r,$template,$ids,$d){$old=DB::table('review_templates')->where('id',$template)->lockForUpdate()->first();abort_unless($old&&in_array($old->programme_id,$ids),404);abort_if(DB::table('review_assignments')->where('template_id',$template)->exists(),409,'This template is used in a review and cannot be edited. Create a separate template instead.');DB::table('review_templates')->where('id',$template)->update(['programme_id'=>$d['programme_id'],'name'=>$d['name'],'kind'=>$d['kind'],'criteria'=>json_encode($d['criteria']),'updated_at'=>now()]);A::audit($r->user(),'template.updated','template',$template,['before'=>['name'=>$old->name,'kind'=>$old->kind,'criteria'=>$old->criteria],'after'=>$d],$old->programme_id);return ['message'=>'Template updated.'];});}
 public function deleteTemplate(Request $r,int $template,ProgrammeAccess $a){$ids=$a->programmes($r->user(),'templates.manage');abort_unless($ids,403);return DB::transaction(function()use($r,$template,$ids){$old=DB::table('review_templates')->where('id',$template)->lockForUpdate()->first();abort_unless($old&&in_array($old->programme_id,$ids),404);abort_if(DB::table('review_assignments')->where('template_id',$template)->exists(),409,'This template is used in a review and cannot be deleted.');DB::table('review_templates')->where('id',$template)->delete();A::audit($r->user(),'template.deleted','template',$template,['name'=>$old->name,'kind'=>$old->kind],$old->programme_id);return response()->noContent();});}
 public function listTemplates(Request $r,ProgrammeAccess $a){$ids=$a->programmes($r->user(),'templates.manage');abort_unless($ids,403);return ['templates'=>DB::table('review_templates')->whereIn('programme_id',$ids)->select('review_templates.*')->selectRaw('(SELECT COUNT(*) FROM review_assignments WHERE review_assignments.template_id = review_templates.id) as use_count')->orderBy('programme_id')->orderBy('name')->get(),'programmes'=>DB::table('programmes')->whereIn('id',$ids)->orderBy('name')->get()];}
 public function availability(Request $r){$d=$r->validate(['availability'=>['required',Rule::in(['available','unavailable'])]]);$r->user()->availability=$d['availability'];$r->user()->save();A::audit($r->user(),'availability.changed','user',$r->user()->id,$d);if($d['availability']==='available')foreach((new ProgrammeAccess)->programmes($r->user(),'reviews.evaluate') as $id)(new AutoAllocator)->assignReady($id);return ['message'=>'Availability updated.'];}
 public function history(Request $r,Idea $idea,ProgrammeAccess $a){abort_unless(in_array($idea->programme_id,$this->scope($r,$a)),404);return ['data'=>DB::table('audit_events')->where('subject_type','idea')->where('subject_id',$idea->id)->orderByDesc('id')->limit(100)->get()];}
}

